function hasCap: boolean;
var i : integer;
    temp : boolean;
begin
    i := 1;
    temp := false;
    repeat
        if (P[i] >= 'A') and (P[i] <= 'Z') then
            temp := true;
        i := i + 1;
    until temp or (i > N);
    hasCap := temp;
end;

function noSpace : boolean;
var i : integer;
    temp : boolean;
begin
    temp := true;
    for i := 1 to N do
        if (P[i] = ' ') then
            temp := false;
    noSpace := temp;
end;

function checkPassWd : boolean;
begin
    checkPassWd := hasCap and noSpace;
end;

